#include <string.h>

#define MOD 1000000007LL

long long dp[105][4][4][4];

int ok(int a, int b, int c, int d) {
    // Map: 0=A, 1=C, 2=G, 3=T

    // Directly forbidden after appending d
    if (b == 0 && c == 2 && d == 1) return 0; // AGC
    if (b == 0 && c == 1 && d == 2) return 0; // ACG
    if (b == 2 && c == 0 && d == 1) return 0; // GAC

    // Forbidden after one adjacent swap
    if (a == 0 && c == 2 && d == 1) return 0; // A?GC
    if (a == 0 && b == 2 && d == 1) return 0; // AG?C

    return 1;
}

int main(void) {
    int N;
    scanf("%d", &N);

    // 3 is used as sentinel/start character T, which is safe.
    dp[0][3][3][3] = 1;

    for (int i = 0; i < N; i++) {
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                for (int c = 0; c < 4; c++) {
                    long long cur = dp[i][a][b][c];
                    if (!cur) continue;
                    for (int d = 0; d < 4; d++) {
                        if (ok(a, b, c, d)) {
                            dp[i + 1][b][c][d] += cur;
                            if (dp[i + 1][b][c][d] >= MOD) dp[i + 1][b][c][d] -= MOD;
                        }
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int a = 0; a < 4; a++) {
        for (int b = 0; b < 4; b++) {
            for (int c = 0; c < 4; c++) {
                ans += dp[N][a][b][c];
                if (ans >= MOD) ans -= MOD;
            }
        }
    }

    printf("%lld\n", ans);
    return 0;
}

