static const long long MOD = 1000000007LL;

// Check whether a 4-character string is valid:
// it must not contain "AGC" even after at most one adjacent swap inside it.
bool ok(const string& s) {
    for (int i = 0; i < 4; i++) {
        string t = s;
        if (i >= 1) swap(t[i - 1], t[i]);
        bool bad = false;
        for (int j = 0; j + 2 < 4; j++) {
            if (t.substr(j, 3) == "AGC") bad = true;
        }
        if (bad) return false;
    }
    return true;
}

