    for (int i = 0; i < N; i++) {
        ndp.clear();
        for (auto &[last3, cnt] : dp) {
            for (char c : chars) {
                string s = last3 + c; // length 4
                if (ok(s)) {
                    string nxt = s.substr(1, 3);
                    ndp[nxt] = (ndp[nxt] + cnt) % MOD;
                }
            }
        }
        dp.swap(ndp);
    }

    long long ans = 0;
    for (auto &[k, v] : dp) {
        ans = (ans + v) % MOD;
    }

    cout << ans % MOD << '\n';
