}

import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        sc.close();

        if (N == 1) {
            System.out.println(4);
            return;
        }
        if (N == 2) {
            System.out.println(16);
            return;
        }

        // dp[i][a][b][c] = number of valid strings of length i ending with chars a,b,c (0:A,1:C,2:G,3:T)
        int[][][][] dp = new int[N + 1][4][4][4];

        // Initialize for length 3
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                for (int c = 0; c < 4; c++) {
                    if (isValid(a, b, c)) {
                        dp[3][a][b][c] = 1;
                    }
                }
            }
        }

        for (int i = 4; i <= N; i++) {
            for (int a = 0; a < 4; a++) {
                for (int b = 0; b < 4; b++) {
                    for (int c = 0; c < 4; c++) {
                        if (dp[i - 1][a][b][c] == 0) continue;
                        for (int d = 0; d < 4; d++) {
                            if (isValid(b, c, d) && isValid(a, b, d) && isValid(a, c, d)) {
                                dp[i][b][c][d] = (dp[i][b][c][d] + dp[i - 1][a][b][c]) % MOD;
                            }
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                for (int c = 0; c < 4; c++) {
                    ans = (ans + dp[N][a][b][c]) % MOD;
                }
            }
        }
        System.out.println(ans);
    }

    static boolean isValid(int x, int y, int z) {
        // 0:A,1:C,2:G,3:T
        // Direct AGC
        if (x == 0 && y == 2 && z == 1) return false; // A G C
        // Swap adjacent 1&2 -> GAC
        if (x == 2 && y == 0 && z == 1) return false; // G A C
        // Swap adjacent 2&3 -> ACG
        if (x == 0 && y == 1 && z == 2) return false; // A C G
        // A?GC pattern: x==0, z==1, y arbitrary but we also need to check length-4 context
        // This check is done in the transition for length 4 with the extra conditions
        return true;
    }

    static boolean isValid(char a, char b, char c) {
        return isValid(toInt(a), toInt(b), toInt(c));
    }

    static int toInt(char ch) {
        switch (ch) {
            case 'A': return 0;
            case 'C': return 1;
            case 'G': return 2;
            case 'T': return 3;
        }
        return -1;
    }
}

