public class Main {
    static final long MOD = 1_000_000_007L;

    static int code(char c) {
        if (c == 'A') return 0;
        if (c == 'C') return 1;
        if (c == 'G') return 2;
        return 3; // T
    }

    static char ch(int x) {
        return "ACGT".charAt(x);
    }

    static boolean valid(char a, char b, char c, char d) {
        char[] s = {a, b, c, d};

        // check original and all strings obtained by one adjacent swap
        for (int t = 0; t < 4; t++) {
            char[] x = s.clone();
            if (t < 3) {
                char tmp = x[t];
                x[t] = x[t + 1];
                x[t + 1] = tmp;
            }
            for (int i = 0; i + 2 < 4; i++) {
                if (x[i] == 'A' && x[i + 1] == 'G' && x[i + 2] == 'C') return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        long[][][][] dp = new long[N + 1][4][4][4];

        int T = code('T');
        dp[0][T][T][T] = 1;

        for (int i = 0; i < N; i++) {
            for (int a = 0; a < 4; a++) {
                for (int b = 0; b < 4; b++) {
                    for (int c = 0; c < 4; c++) {
                        long cur = dp[i][a][b][c];
                        if (cur == 0) continue;
                        for (int d = 0; d < 4; d++) {
                            if (valid(ch(a), ch(b), ch(c), ch(d))) {
                                dp[i + 1][b][c][d] += cur;
                                if (dp[i + 1][b][c][d] >= MOD) dp[i + 1][b][c][d] -= MOD;
                            }
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                for (int c = 0; c < 4; c++) {
                    ans += dp[N][a][b][c];
                    if (ans >= MOD) ans -= MOD;
                }
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

