MOD = 10**9 + 7

def main():
    N = int(sys.stdin.readline())

    chars = ['A', 'C', 'G', 'T']

    # Check whether a 4-character string is valid:
    # it must not contain "AGC" even after at most one adjacent swap
    def ok(s):
        s = list(s)
        for i in range(4):
            t = s[:]
            if i >= 1:
                t[i - 1], t[i] = t[i], t[i - 1]
            u = ''.join(t)
            if "AGC" in u:
                return False
        return True

    # DP over last 3 characters
    dp = {"TTT": 1}

    for _ in range(N):
        ndp = {}
        for last3, cnt in dp.items():
            for c in chars:
                s = last3 + c
                if ok(s):
                    nxt = s[1:]
                    ndp[nxt] = (ndp.get(nxt, 0) + cnt) % MOD
        dp = ndp

    print(sum(dp.values()) % MOD)

